// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e18);

        // Adversarial counterparty: a contract that re-enters withdrawBalance
        // exactly once during the first withdrawal (swallowing the revert that
        // the reentrancy guard legitimately causes), so a second withdrawal
        // afterwards is a fresh guarded entry.
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Deposit from the attacker contract.
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();
        assertTrue(c.getBalance(address(attacker)) == amount, "deposit credited");

        // First withdrawal: succeeds; the helper re-enters once (revert swallowed).
        vm.prank(address(attacker));
        try c.withdrawBalance() {
            // succeeded
        } catch {
            assertTrue(false, "first withdraw failed");
        }
        assertTrue(c.getBalance(address(attacker)) == 0, "balance cleared");

        // RULE: after any completed guarded call, the lock is released, so a
        // later withdrawBalance by the same actor must succeed again.
        bool ok;
        vm.prank(address(attacker));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "a completed guarded call must release the lock so later withdrawals succeed");
    }
}

contract ReentrantAttacker {
    Reentrance private c;
    bool private entered;
    constructor(Reentrance _c) { c = _c; }
    receive() external payable {
        if (!entered) {
            entered = true;
            try c.withdrawBalance() { } catch { }
        }
    }
}
